package com.tripmateai.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; @Component @RequiredArgsConstructor public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt;private final CustomUserDetailsService users; protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{var h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){var t=h.substring(7);if(jwt.valid(t)){var u=users.loadUserByUsername(jwt.subject(t));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities()));}}c.doFilter(r,s);}}
